Here's a comprehensive C++ solution using Qt5 that accomplishes file directory selection and Excel to CSV conversion:

```cpp
#include <QApplication>
#include <QMainWindow>
#include <QFileDialog>
#include <QMessageBox>
#include <QDir>
#include <QDebug>
#include <QXlsx/xlsxdocument.h>
#include <QTextStream>

class ExcelConverterApp : public QMainWindow {
    Q_OBJECT

public:
    ExcelConverterApp() : QMainWindow() {
        setWindowTitle("Excel to CSV Converter");
        resize(400, 200);
        setupUI();
    }

private:
    void setupUI() {
        QPushButton* selectButton = new QPushButton("Select Directory", this);
        selectButton->setGeometry(100, 80, 200, 40);
        connect(selectButton, &QPushButton::clicked, this, &ExcelConverterApp::selectDirectoryAndConvert);
    }

    void selectDirectoryAndConvert() {
        QString directory = QFileDialog::getExistingDirectory(
            this,
            "Select Excel Files Directory",
            QDir::homePath(),
            QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks
        );

        if (directory.isEmpty()) {
            return;
        }

        QDir sourceDir(directory);
        QDir csvDir(directory + "/CSV_Exports");

        if (!csvDir.exists()) {
            csvDir.mkpath(".");
        }

        QStringList excelExtensions = {"*.xlsx", "*.xls", "*.xlsm"};
        QFileInfoList excelFiles = sourceDir.entryInfoList(excelExtensions, QDir::Files);

        int convertedCount = 0;
        int failedCount = 0;

        for (const QFileInfo& fileInfo : excelFiles) {
            try {
                if (convertExcelToCSV(fileInfo.absoluteFilePath(), csvDir.absolutePath())) {
                    convertedCount++;
                } else {
                    failedCount++;
                }
            } catch (...) {
                failedCount++;
            }
        }

        QMessageBox::information(
            this, 
            "Conversion Complete", 
            QString("Converted %1 files\nFailed to convert %2 files")
            .arg(convertedCount)
            .arg(failedCount)
        );
    }

    bool convertExcelToCSV(const QString& excelFilePath, const QString& outputDir) {
        QXlsx::Document xlsx(excelFilePath);

        if (!xlsx.isValid()) {
            qDebug() << "Invalid Excel file:" << excelFilePath;
            return false;
        }

        // Get the filename without extension
        QFileInfo fileInfo(excelFilePath);
        QString baseName = fileInfo.baseName();

        for (int sheetIndex = 1; sheetIndex <= xlsx.sheetCount(); ++sheetIndex) {
            QString sheetName = xlsx.sheetNames().at(sheetIndex - 1);
            QString csvFilePath = QString("%1/%2_%3.csv")
                .arg(outputDir, baseName, sheetName);

            QFile csvFile(csvFilePath);
            if (!csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) {
                qDebug() << "Could not open CSV file for writing:" << csvFilePath;
                return false;
            }

            QTextStream out(&csvFile);

            int rows = xlsx.dimension().rowCount();
            int cols = xlsx.dimension().columnCount();

            for (int row = 1; row <= rows; ++row) {
                QStringList rowData;
                for (int col = 1; col <= cols; ++col) {
                    QVariant cellValue = xlsx.cellAt(row, col)->value();
                    rowData << cellValue.toString();
                }
                out << rowData.join(",") << "\n";
            }

            csvFile.close();
        }

        return true;
    }
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);
    ExcelConverterApp converterApp;
    converterApp.show();
    return app.exec();
}

#include "main.moc"
```

To use this code, you'll need:

1. Qt5 Development Libraries
2. QtXlsx Library (for Excel file handling)

CMakeLists.txt example:
```cmake
cmake_minimum_required(VERSION 3.10)
project(ExcelConverter)

set(CMAKE_CXX_STANDARD 14)
set(CMAKE_AUTOMOC ON)
set(CMAKE_AUTORCC ON)
set(CMAKE_AUTOUIC ON)

find_package(Qt5 COMPONENTS Widgets REQUIRED)
find_package(Qt5Xlsx REQUIRED)

add_executable(ExcelConverter main.cpp)
target_link_libraries(ExcelConverter 
    Qt5::Widgets 
    Qt5::Xlsx
)
```

Features:
- Select directory containing Excel files
- Converts all Excel files in directory to CSV
- Creates a "CSV_Exports" subdirectory
- Handles multiple sheets per workbook
- Shows conversion summary
- Error handling for file reading/writing

Installation Notes:
1. Install Qt5 development libraries
2. Install QtXlsx (can be found on GitHub)
3. Ensure necessary dependencies are linked

Build and run with CMake and your preferred C++ compiler.

